using System;using System.IO;using System.Linq;using UnityEngine;using UnityEditor;using Demo6.Game;
public static class TextureV7Inspect {
 public static object Run(){var d=DungeonRoot.Instance;var c=d.CurrentCell;string root="검증/텍스처-시범-v7/baseline";Directory.CreateDirectory(root);var floors=UnityEngine.Object.FindObjectsByType<SpriteRenderer>().Where(s=>s.sprite&&s.sprite.name=="Dungeon floor"&&Vector2.Distance(s.transform.position,c.Center)<.1f).ToArray();foreach(var s in floors)Save(s.sprite.texture,root+"/entry_floor.png");var wall=ShapeSprites.StoneWall(new Rect(0,0,8,8));Save(wall.texture,root+"/wall_tile.png");UnityEngine.Object.Destroy(wall.texture);UnityEngine.Object.Destroy(wall);var rows=UnityEngine.Object.FindObjectsByType<SpriteRenderer>().Where(s=>s.sprite&&(s.sprite.name=="Dungeon wall"||s.sprite.name=="Dungeon rock")&&s.bounds.Intersects(new Bounds(c.Center,new Vector3(c.Bounds.width,c.Bounds.height,1)))).Select(s=>new{name=s.name,parent=s.transform.parent?s.transform.parent.name:"",sprite=s.sprite.name,size=s.bounds.size.ToString(),position=s.transform.position.ToString()}).ToArray();File.WriteAllText(root+"/world.json",Newtonsoft.Json.JsonConvert.SerializeObject(new{cell=c.Id,bounds=c.Bounds.ToString(),floorCount=floors.Length,walls=rows},Newtonsoft.Json.Formatting.Indented));return new{cell=c.Id,bounds=c.Bounds.ToString(),floors=floors.Length,walls=rows};}
 static void Save(Texture2D source,string path){if(source.isReadable){File.WriteAllBytes(path,source.EncodeToPNG());return;}var rt=RenderTexture.GetTemporary(source.width,source.height,0,RenderTextureFormat.ARGB32,RenderTextureReadWrite.sRGB);var old=RenderTexture.active;Graphics.Blit(source,rt);RenderTexture.active=rt;var t=new Texture2D(source.width,source.height,TextureFormat.RGBA32,false);t.ReadPixels(new Rect(0,0,source.width,source.height),0,0);t.Apply();File.WriteAllBytes(path,t.EncodeToPNG());RenderTexture.active=old;RenderTexture.ReleaseTemporary(rt);UnityEngine.Object.Destroy(t);}
}
